/// The Italic face as outlines, which it is drawn from at any size: face 4.
pub static ITALIC: Face = Face::new(4, UPEM, [984, 316, 0], &GLYPHS, &KERNING);

// Checked when this module compiles: the outlines exactly the face's characters, in order;
// every outline's steps taking exactly its points, the outlines taking all of VERBS and
// POINTS; every step a known one and every point inside its outline's box. The values are
// checked by `make atlases-check`, which makes them again and compares them byte for byte.
const _: () = assert!(outlines_fit(&GLYPHS, &CHARS, VERBS.len(), POINTS.len()));
